export function manfredNative(r,n){
 const stats=STATS[r?.level],t=r?.talents?.bb??{};
 if(!isManfred(r)||!stats||r.applyWay!=="RANGED"||r.stats.rangeRadius!==2||r.stats.bat!==5||r.stats.blockCnt!==1||r.notCountInTotal
  ||Object.entries(stats).some(([k,v])=>r.stats[k]!==v)||!same(r.abilities,MANFRED_ABILITIES)
  ||!same(omit(t),omit(T))||Object.entries(MANFRED_STAGE_OVERRIDES).some(([k,ok])=>!ok(t[k]))
  ||!same(r.talents.bbStr,TS)||!same(r.talents.groups,GROUPS)||!same(r.skills,SKILLS))return false;
 if(!same(closure(n),COMPONENTS)||Object.entries(TEMPLATES).some(([k,v])=>!same(n.$template(k),v))
  ||Object.entries(PROJECTILES).some(([k,v])=>!same(n.$projectile(k).map(c=>JSON.stringify(norm(c))).sort(),v)))return false;
 const root=n[r.prefabKey]?.find(v=>"_modes"in v),graphic=n.$ref(root?._animator),clock=clocks.enemies[r.prefabKey];
 return !!clock&&n.$ref(graphic?._skeleton)?.skeletonDataAsset?.m_PathID===clock.source?.skeletonDataPathId
  &&Object.entries(CLOCK.durations).every(([k,v])=>clock.durations[k]===v)&&!clock.events.Revive
  &&Object.entries(CLOCK.events).every(([k,v])=>clock.events[k]?.length===1&&clock.events[k][0].name==="OnAttack"&&clock.events[k][0].time===v);
}
/** Runtime parameters from the talents, the skills, the pinned components (funnel projectile and bounce) and clips. */
export function manfredParams(r){
 const t=r.talents.bb,rage=r.skills.find(s=>s.prefabKey==="Funnel_rage");
 const anim=k=>({dur:CLOCK.durations[k],hit:CLOCK.events[k]});
 return {
  // Both attack triggers select one ground operator (_targetMotion 1); their placeholder colliders (0.5) are sized by the
  // record's range. Form one: the cannon's 50% Arts normal attack. Form two: the sword's Physical normal attack (_atkScale 1).
  radius:r.stats.rangeRadius,
  form1:{scale:t["Funnel_s1.attack@atk_scale"],type:"arts",ep:t["Funnel_s1.attack@ep_damage_ratio"],anim:anim("Attack_1")},
  form2:{scale:1,type:"phys",ep:t["Funnel_s2.attack@ep_damage_ratio"],anim:anim("Attack_2")},
  // Element 4 on all three damaging abilities is Necrosis (PRTS H10-1: 凋亡损伤).
  element:"apoptosis",
  focus:{aspd:t["Funnel_common.attack@attack_speed"],max:t["Funnel_common.attack@max_stack_cnt"],hold:t["Funnel_common.attack@duration"]},
  charge:{attack:t["Funnel_s1_charge.sp"],funnel:t["Funnel_s2_charge.sp"],rage:t["Funnel_rage_charge.sp"]},
  // projectile_enemy_manfri_funnel: speed 20; a bounce controller with one hit per `times`, 0.53 s apart, the next
  // target one other operator within its 1.5 selector, else the traced target again (_hitTraceTargetIfNoOtherTarget).
  funnel:{scale:t["Funnel_s2.atk_scale"],ep:t["Funnel_s2.ep_damage_ratio"],times:t["Funnel_s2.times"],speed:20,
   bounceRadius:1.5,bounceInterval:f32(.5264827013015747)},
  evade:{prob:t["Shield.prob"],disable:t["Shield.disable_duration"],stun:t["Shield[disable].stun"]},
  // PRTS: a 20 s revive at 100% HP (the native _hpRechargeRatio is 1 here), a cannon shot every 0.8 s at one random
  // ground operator for 30% ATK Arts; then the Pose cast (the 5 s Revive clip) and 5 s of invincibility.
  rebirth:{dur:t["Reborn.duration"],interval:t["Reborn.interval"],invincible:t["Reborn.invincible"],rageScale:rage.bb.atk_scale,pose:CLOCK.durations.Revive},
 };
}
